arguments.command:
/bin/bash -lc "python - <<'PY'
import json,collections
for f in ['data_evidence/train.jsonl','data_evidence/val.jsonl']:
 c=collections.Counter(); faults=collections.Counter()
 for l in open(f):
  x=json.loads(l); c[x['data_source']]+=1; s=json.loads(x['extra_info']['scenario_json']); faults[(x['data_source'],s['fault_after_commit'])]+=1
 print(f,c,faults)
PY
# inspect trace event timeout prevalence
python - <<'PY'
import json,glob,collections
c=collections.Counter();
for f in glob.glob('outputs/tool_events/*.json'):
 try:
  x=json.load(open(f));
  txt=json.dumps(x)
  for k in ['timeout','turn_limit','finish','reused_receipt']: c[k]+=txt.count(k)
 except: pass
print(c)
PY
# tail train log
 tail -40 outputs/train.log"

/bin/bash -lc "grep -nE 'Native checkpoint pause|Resuming from|Training Progress: 100%|response_length/clip_ratio|response/aborted_ratio|global_step' outputs/train.log | tail -30; python - <<'PY'
import json
for l in open('outputs/metrics.jsonl'):
 d=json.loads(l); x=d['data'];
 if d['step'] in [0,5,10,15,20,25,30]:
  print(d['step'],x.get('inventory/ordinary_success'),x.get('inventory/unseen_success'),x.get('response_length/clip_ratio'),x.get('response/aborted_ratio'),x.get('timing_s/step'))
PY"

